    }} footer={<aside>Footer {count}</aside>}>
      Ordinary children <b>{((enabled ? <Box>Question {account.name}</Box> : <Box>{fallback}</Box>) satisfies React.ReactNode)}</b>
    </Card></Shell>;
      },
      get empty() { return <p>Independent getter page</p>; },
    };

